sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', health_results: [], summary: { passed: 0, failed: 0 } };
  try {
    var plugins = JSON.parse(inputs.upgraded_plugins);

    for (var i = 0; i < plugins.length; i++) {
      var plugin = plugins[i];
      var health = {
        plugin_name: plugin.plugin_name || plugin.name,
        sys_id: plugin.sys_id || plugin.plugin_sys_id,
        checks: [],
        overall_status: 'passed'
      };

      var gr = new GlideRecordSecure('sys_plugins');
      if (gr.get(health.sys_id)) {
        // Check 1: Activation status
        var isActive = gr.getValue('active');
        if (isActive === 'active') {
          health.checks.push({ check: 'Activation Status', result: 'PASS', detail: 'Plugin is active' });
        } else {
          health.checks.push({ check: 'Activation Status', result: 'FAIL', detail: 'Plugin is not active' });
          health.overall_status = 'failed';
        }

        // Check 2: Version confirmation
        var currentVersion = gr.getValue('version') || 'unknown';
        health.checks.push({ 
          check: 'Version Verification', 
          result: 'PASS', 
          detail: 'Current version: ' + currentVersion 
        });

        // Check 3: Basic accessibility
        health.checks.push({ check: 'Record Accessible', result: 'PASS', detail: 'Plugin record is readable' });

      } else {
        health.checks.push({ check: 'Plugin Existence', result: 'FAIL', detail: 'Plugin record not found' });
        health.overall_status = 'failed';
      }

      if (health.overall_status === 'passed') {
        result.summary.passed++;
      } else {
        result.summary.failed++;
      }

      result.health_results.push(health);
    }
  } catch (e) {
    result.status = 'error';
    result.message = 'Health check failed: ' + e.message;
  }
  return result;
})(inputs);
